"""Usage: python3 emit.py GEN.py Module Doc  -> writes formal/ZP/<Module>.lean (generated).
GEN.py is run (its stdout is the theorem text)."""
import os, subprocess, sys
here = os.path.dirname(os.path.abspath(__file__))
gen, mod, doc = sys.argv[1], sys.argv[2], sys.argv[3]
body = subprocess.run([sys.executable, os.path.join(here, gen)], capture_output=True, text=True, cwd=here)
if body.stderr.strip():
    print(body.stderr, file=sys.stderr)
    sys.exit(1)
hdr = ("module\n\npublic import ZP.MMPair\n\n@[expose] public section\n\n"
       "/-! %s (generated by `scripts/mm/emit.py %s`). -/\n\nnamespace ZP.Mul.MM\n\nopen ZP\n\n" % (doc, gen))
out = os.path.join(here, '..', '..', 'ZP', mod + '.lean')
open(out, 'w').write(hdr + body.stdout + "\nend ZP.Mul.MM\n")
print('wrote', out)
